.solicitud-eliminacion-pendiente-widget {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  z-index: 25;
}

/* Funcionarios y Accesos */
.dashboard-topbar-user--menu {
    position: relative;
    cursor: pointer;
}

.dashboard-topbar-user__status {
    position: absolute;
    right: 5px;
    bottom: 6px;
    width: 10px;
    height: 10px;
    border: 2px solid #ffffff;
    border-radius: 50%;
    background: #f59e0b;
    box-sizing: border-box;
}

.dashboard-topbar-user__status--danger {
    background: #dc2626;
}

.dashboard-topbar-user__status--warning {
    background: #f59e0b;
}

.dashboard-topbar-user-menu {
    position: absolute;
    top: calc(100% + 8px);
    left: 0;
    z-index: 50;
    width: 220px;
    padding: 6px;
    border: 1px solid #d8e2ee;
    border-radius: 8px;
    background: #ffffff;
    box-shadow: 0 16px 36px rgba(15, 23, 42, 0.16);
    box-sizing: border-box;
}

.dashboard-topbar-user-menu button {
    width: 100%;
    min-height: 34px;
    padding: 8px 10px;
    border: 0;
    border-radius: 6px;
    background: transparent;
    color: #172033;
    font-family: "Merriweather Sans", Arial;
    font-size: 12px;
    font-weight: 800;
    text-align: left;
    cursor: pointer;
}

.dashboard-topbar-user-menu button:hover {
    background: #f2f6fb;
}

.funcionarios-shell {
    width: calc(100vw - 16px) !important;
    max-width: none !important;
    max-height: calc(100vh - 16px);
    overflow: auto;
    padding: 10px !important;
    box-sizing: border-box;
}

.funcionarios-shell > .tableMenuZ,
.funcionarios-shell > center,
.funcionarios-shell > #table_abm_usuarios {
    display: none !important;
}

.funcionarios-modern {
    display: grid;
    gap: 12px;
    color: #172033;
    font-family: "Merriweather Sans", Arial;
}

.funcionarios-header,
.funcionarios-search,
.funcionarios-filters,
.funcionario-selected-actions,
.funcionarios-layout,
.funcionario-ficha {
    box-sizing: border-box;
}

.funcionarios-header {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 12px;
    padding-bottom: 12px;
    border-bottom: 1px solid #e4e7ec;
}

.funcionarios-header__title {
    margin: 0;
    color: #172033;
    font-size: 25px;
    font-weight: 900;
    line-height: 1.15;
}

.funcionarios-header__help {
    margin: 4px 0 0;
    color: #667085;
    font-size: 12px;
    font-weight: 700;
    line-height: 1.35;
}

.funcionarios-header__actions,
.funcionario-selected-actions__buttons,
.funcionario-ficha__actions {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 8px;
}

.funcionarios-primary-button,
.funcionarios-secondary-button,
.funcionarios-icon-button,
.funcionario-filter,
.funcionario-selected-actions__buttons button,
.funcionario-ficha__actions button,
.mi-perfil-status button,
.mi-perfil-domicilio__actions button {
    min-height: 34px;
    border: 1px solid #d8e2ee;
    border-radius: 8px;
    font-family: "Merriweather Sans", Arial;
    font-size: 12px;
    font-weight: 900;
    cursor: pointer;
    box-sizing: border-box;
}

.funcionarios-primary-button {
    padding: 0 14px;
    border-color: #1178b3;
    background: #1178b3;
    color: #ffffff;
}

.funcionarios-secondary-button,
.funcionario-selected-actions__buttons button,
.funcionario-ficha__actions button {
    padding: 0 12px;
    background: #ffffff;
    color: #172033;
}

.funcionarios-icon-button {
    width: 36px;
    padding: 0;
    display: inline-grid;
    place-items: center;
    background: #ffffff;
}

.funcionarios-icon-button img {
    width: 18px;
    height: 18px;
    object-fit: contain;
}

.funcionarios-search {
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto;
    gap: 8px;
}

.funcionarios-search__input {
    width: 100%;
    height: 44px;
    padding: 0 14px;
    border: 1px solid #cbd5e1;
    border-radius: 8px;
    background: #ffffff;
    color: #172033;
    font-size: 14px;
    font-weight: 800;
    box-sizing: border-box;
}

.funcionarios-filters {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
    align-items: center;
}

.funcionario-filter {
    padding: 0 12px;
    background: #ffffff;
    color: #475467;
}

.funcionario-filter--active {
    border-color: #159947;
    background: #e9f8ee;
    color: #137f3f;
}

.funcionario-check {
    min-height: 34px;
    display: inline-flex;
    align-items: center;
    gap: 6px;
    padding: 0 10px;
    border: 1px solid #e4e7ec;
    border-radius: 8px;
    background: #f8fafc;
    color: #475467;
    font-size: 11px;
    font-weight: 800;
}

.funcionario-select {
    min-height: 34px;
    max-width: 210px;
    padding: 0 10px;
    border: 1px solid #d8e2ee;
    border-radius: 8px;
    background: #ffffff;
    color: #172033;
    font-size: 11px;
    font-weight: 800;
}

.funcionario-selected-actions {
    min-height: 58px;
    padding: 10px 12px;
    border: 1px solid #d8e2ee;
    border-radius: 8px;
    background: #f8fafc;
}

.funcionario-selected-actions__empty {
    min-height: 36px;
    display: flex;
    align-items: center;
    color: #667085;
    font-size: 12px;
    font-weight: 900;
}

.funcionario-selected-actions__content {
    display: grid;
    grid-template-columns: minmax(190px, 1fr) auto auto;
    align-items: center;
    gap: 10px;
}

.funcionario-selected-actions__summary {
    min-width: 0;
    display: grid;
    gap: 2px;
}

.funcionario-selected-actions__summary span {
    color: #667085;
    font-size: 10px;
    font-weight: 900;
    text-transform: uppercase;
}

.funcionario-selected-actions__summary strong {
    overflow: hidden;
    color: #172033;
    font-size: 14px;
    font-weight: 900;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.funcionario-selected-actions__summary small {
    overflow: hidden;
    color: #667085;
    font-size: 11px;
    font-weight: 800;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.funcionario-selected-actions__badges {
    display: flex;
    flex-wrap: wrap;
    justify-content: flex-end;
    gap: 6px;
}

.funcionario-selected-actions__buttons {
    justify-content: flex-end;
}

.funcionario-selected-actions__buttons button {
    min-height: 30px;
    padding: 0 10px;
    font-size: 11px;
}

.funcionarios-layout {
    display: block;
}

.funcionarios-listado {
    width: 100%;
    min-width: 0;
    border: 1px solid #e4e7ec;
    border-radius: 8px;
    background: #ffffff;
}

.funcionarios-listado {
    overflow: hidden;
}

.funcionarios-listado__head,
.funcionario-row {
    display: grid;
    grid-template-columns: 48px minmax(0, 1.8fr) minmax(0, .75fr) minmax(0, .9fr) minmax(0, 1fr) minmax(0, .8fr) minmax(0, .7fr) minmax(0, .9fr) minmax(0, .65fr);
    align-items: center;
    gap: 8px;
}

.funcionarios-listado__head {
    padding: 9px 10px;
    background: #f2f6fb;
    color: #475467;
    font-size: 10px;
    font-weight: 900;
    text-transform: uppercase;
}

.funcionarios-listado__body {
    min-height: 360px;
    max-height: calc(94vh - 314px);
    overflow-x: hidden;
    overflow-y: auto;
}

.funcionario-row {
    min-height: 64px;
    padding: 8px 10px;
    border-top: 1px solid #edf1f5;
    color: #172033;
    font-size: 12px;
    font-weight: 700;
    cursor: pointer;
    box-sizing: border-box;
}

.funcionario-row:hover,
.funcionario-row--selected {
    background: #f8fafc;
}

.funcionario-row__avatar,
.funcionario-ficha__avatar {
    object-fit: cover;
    object-position: center;
    border-radius: 50%;
    border: 2px solid #e4e7ec;
    background: #f8fafc;
}

.funcionario-row__avatar {
    width: 42px;
    height: 42px;
}

.funcionario-row__person {
    min-width: 0;
    display: grid;
    gap: 2px;
}

.funcionarios-listado__head span,
.funcionario-row > span {
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.funcionario-row__person strong {
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    font-size: 12px;
}

.funcionario-row__person small {
    overflow: hidden;
    text-overflow: ellipsis;
    color: #667085;
    font-size: 10px;
    font-weight: 800;
    white-space: nowrap;
}

.funcionario-badge {
    width: max-content;
    max-width: 100%;
    padding: 4px 8px;
    border-radius: 999px;
    font-size: 10px;
    font-weight: 900;
    line-height: 1.1;
}

.funcionario-badge--success {
    background: #e9f8ee;
    color: #137f3f;
}

.funcionario-badge--danger {
    background: #fee2e2;
    color: #b42318;
}

.funcionario-badge--muted {
    background: #eef2f7;
    color: #475467;
}

.funcionario-row > .funcionario-badge {
    width: auto;
    justify-self: start;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.funcionario-row__progress {
    min-width: 0;
    display: grid;
    gap: 3px;
}

.funcionario-row__progress div,
.funcionario-progress__bar {
    width: 100%;
    height: 7px;
    overflow: hidden;
    border-radius: 999px;
    background: #e4e7ec;
}

.funcionario-row__progress span,
.funcionario-progress__bar span {
    display: block;
    height: 100%;
    border-radius: inherit;
    background: #159947;
}

.funcionario-row__progress small {
    color: #667085;
    font-size: 10px;
    font-weight: 900;
}

.funcionarios-empty,
.funcionario-empty-state {
    padding: 18px;
    color: #667085;
    font-size: 12px;
    font-weight: 800;
    text-align: center;
}

.funcionario-progress {
    width: 100%;
    display: grid;
    gap: 5px;
}

.funcionario-progress small {
    color: #475467;
    font-size: 11px;
    font-weight: 900;
}

/* Consola RR.HH. - Etapa 1 */
.funcionarios-header__eyebrow {
    margin: 0 0 3px;
    color: #1178b3;
    font-size: 10px;
    font-weight: 900;
    text-transform: uppercase;
}

.funcionarios-filters--rrhh {
    gap: 6px;
}

.funcionarios-filters--secondary {
    padding-top: 2px;
}

.funcionarios-layout--rrhh {
    display: grid !important;
    grid-template-columns: minmax(0, 1fr) 330px;
    gap: 10px;
    align-items: start;
}

.funcionarios-layout--rrhh .funcionarios-listado {
    width: auto !important;
}

.funcionarios-layout--rrhh .funcionarios-listado__head,
.funcionario-row--rrhh {
    grid-template-columns: minmax(230px, 1.1fr) minmax(126px, .42fr) minmax(280px, 1.45fr) minmax(126px, .4fr);
}

.funcionario-row--rrhh {
    min-height: 60px;
}

.funcionarios-modern .funcionario-row--resumen {
    transition: background .16s ease, border-color .16s ease;
}

.funcionarios-modern .funcionario-row--expanded {
    background: #f8fafc;
}

.funcionario-row--rrhh .funcionario-row__person {
    display: grid;
    grid-template-columns: 38px minmax(0, 1fr);
    align-items: center;
    gap: 8px;
}

.funcionario-row--rrhh .funcionario-row__avatar {
    width: 34px;
    height: 34px;
}

.funcionario-row--rrhh .funcionario-row__person small {
    white-space: normal;
    line-height: 1.2;
}

.funcionario-cell {
    min-width: 0;
    display: grid;
    gap: 3px;
}

.funcionario-cell strong,
.funcionario-cell small {
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.funcionario-cell strong {
    color: #172033;
    font-size: 11px;
    font-weight: 900;
}

.funcionario-cell small {
    color: #667085;
    font-size: 9px;
    font-weight: 800;
}

.funcionarios-modern .funcionario-cell--persona .funcionario-chip {
    margin-top: 3px;
}

.funcionarios-modern .funcionario-cell--contrato {
    align-content: center;
}

.funcionarios-modern .funcionario-alertas {
    min-width: 0;
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 5px;
}

.funcionarios-modern .funcionario-alertas--detail {
    margin-top: 7px;
}

.funcionarios-modern .funcionario-alert-chip {
    max-width: 100%;
    min-height: 22px;
    display: inline-flex;
    align-items: center;
    padding: 4px 8px;
    overflow: hidden;
    border-radius: 999px;
    font-size: 10px;
    font-weight: 900;
    line-height: 1;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.funcionarios-modern .funcionario-alert-chip--ok {
    background: #e9f8ee;
    color: #137f3f;
}

.funcionarios-modern .funcionario-alert-chip--warning {
    background: #fff7d6;
    color: #8a6100;
}

.funcionarios-modern .funcionario-alert-chip--orange {
    background: #ffedd5;
    color: #b45309;
}

.funcionarios-modern .funcionario-alert-chip--danger {
    background: #fee2e2;
    color: #b42318;
}

.funcionarios-modern .funcionario-alert-chip--info {
    background: #e0f2fe;
    color: #0369a1;
}

.funcionarios-modern .funcionario-alert-chip--purple {
    background: #f3e8ff;
    color: #7e22ce;
}

.funcionarios-modern .funcionario-alert-chip--muted {
    background: #eef2f7;
    color: #475467;
}

.funcionarios-modern .funcionario-row__actions {
    display: inline-flex;
    justify-content: flex-end;
    align-items: center;
    gap: 6px;
}

.funcionarios-modern .funcionario-row__quick,
.funcionarios-modern .funcionario-row__toggle {
    min-height: 30px;
    border: 1px solid #d8e2ee;
    border-radius: 8px;
    background: #ffffff;
    color: #172033;
    font-family: "Merriweather Sans", Arial;
    font-size: 11px;
    font-weight: 900;
    cursor: pointer;
}

.funcionarios-modern .funcionario-row__quick {
    padding: 0 9px;
}

.funcionarios-modern .funcionario-row__toggle {
    width: 32px;
    display: inline-grid;
    place-items: center;
}

.funcionarios-modern .funcionario-row__toggle span {
    font-size: 10px;
    line-height: 1;
}

.funcionarios-modern .funcionario-row__quick:hover,
.funcionarios-modern .funcionario-row__toggle:hover {
    border-color: #1178b3;
    color: #1178b3;
}

.funcionarios-modern .funcionario-row-detail {
    padding: 10px;
    border-top: 1px solid #d8e2ee;
    background: #fbfdff;
    animation: funcionarioDetalleEntrada .16s ease;
}

@keyframes funcionarioDetalleEntrada {
    from {
        opacity: 0;
        transform: translateY(-4px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

.funcionarios-modern .funcionario-detail-grid {
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    gap: 8px;
}

.funcionarios-modern .funcionario-detail-card {
    min-width: 0;
    display: grid;
    align-content: start;
    gap: 8px;
    padding: 10px;
    border: 1px solid #e4e7ec;
    border-radius: 8px;
    background: #ffffff;
}

.funcionarios-modern .funcionario-detail-card h4 {
    margin: 0;
    color: #172033;
    font-size: 12px;
    font-weight: 900;
}

.funcionarios-modern .funcionario-detail-metrics,
.funcionarios-modern .funcionario-detail-control {
    display: grid;
    gap: 6px;
}

.funcionarios-modern .funcionario-detail-metrics > div,
.funcionarios-modern .funcionario-detail-control > div {
    min-width: 0;
    display: grid;
    gap: 4px;
    padding: 7px;
    border-radius: 7px;
    background: #f8fafc;
}

.funcionarios-modern .funcionario-detail-metrics span,
.funcionarios-modern .funcionario-detail-control span,
.funcionarios-modern .funcionario-detail-subblock > span {
    color: #667085;
    font-size: 9px;
    font-weight: 900;
    text-transform: uppercase;
}

.funcionarios-modern .funcionario-detail-metrics strong {
    min-width: 0;
    overflow: hidden;
    color: #172033;
    font-size: 12px;
    font-weight: 900;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.funcionarios-modern .funcionario-detail-metrics small {
    color: #667085;
    font-size: 10px;
    font-weight: 800;
}

.funcionarios-modern .funcionario-detail-subblock {
    display: grid;
    gap: 5px;
}

.funcionarios-modern .funcionario-detail-list {
    margin: 0;
    padding-left: 16px;
    color: #475467;
    font-size: 11px;
    font-weight: 800;
    line-height: 1.35;
}

.funcionarios-modern .funcionario-detail-list--rows {
    display: grid;
    gap: 5px;
    padding-left: 0;
}

.funcionarios-modern .funcionario-detail-row {
    display: grid;
    gap: 2px;
    padding: 7px;
    border-radius: 7px;
    background: #f8fafc;
}

.funcionarios-modern .funcionario-detail-row strong,
.funcionarios-modern .funcionario-detail-row span {
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.funcionarios-modern .funcionario-detail-row strong {
    color: #172033;
    font-size: 11px;
    font-weight: 900;
