        display: none;
    }

    .funcionario-row {
        grid-template-columns: 1fr;
    }

    .funcionario-row > span,
    .funcionario-row__progress,
    .funcionario-row--rrhh > .funcionario-cell,
    .funcionario-row--rrhh > .funcionario-alertas,
    .funcionario-row--rrhh > .funcionario-row__actions {
        grid-column: 1 / -1;
    }

    .funcionario-row--rrhh .funcionario-row__person {
        grid-column: 1 / -1;
    }

    .funcionarios-modern .funcionario-row__actions {
        justify-content: flex-start;
    }

    .funcionarios-modern .funcionario-detail-grid {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }

    .funcionario-ficha__header {
        grid-template-columns: 80px minmax(0, 1fr);
    }

    .funcionario-ficha__actions {
        grid-column: 1 / -1;
    }

    .funcionario-ficha__grid {
        grid-template-columns: 1fr;
    }

    .funcionario-legajo-checklist {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }
}

@media (max-width: 620px) {
    .funcionarios-header,
    .funcionarios-search {
        grid-template-columns: 1fr;
        display: grid;
    }

    .funcionarios-header__actions {
        justify-content: flex-start;
    }

    .funcionario-select,
    .funcionario-check,
    .funcionario-filter {
        width: 100%;
        max-width: none;
    }

    .funcionario-selected-actions__buttons button {
        flex: 1 1 calc(50% - 8px);
    }

    .funcionarios-modern .funcionario-detail-grid {
        grid-template-columns: 1fr;
    }

    .funcionarios-modern .funcionario-detail-actions,
    .funcionarios-modern .funcionario-sanciones-row__actions {
        display: grid;
        grid-template-columns: 1fr;
    }

    .funcionarios-modern .funcionario-detail-action,
    .funcionarios-modern .funcionario-sanciones-row__actions button {
        width: 100%;
    }

    .funcionario-ficha__header {
        grid-template-columns: 1fr;
        justify-items: center;
        text-align: center;
    }

    .funcionario-legajo-checklist {
        grid-template-columns: 1fr;
    }
}
