.vista-consulta {
  /* padding: 1rem; */
  max-height: 100vh;
  overflow-y: auto;
  background: #f9f9f9;
  border-radius: 10px;
}

.vista-consulta-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  background-color: #fff;
  padding: 5px;
  border-bottom: 2px solid #ddd;
}

.titulo-turnos {
  font-size: 1.8rem;
  flex: 1;
  margin: 0;
}

.icono-btn2,
.cerrar-btn img {
  width: 35px;
  height: 35px;
}

.cerrar-btn {
  background: transparent;
  border: none;
  cursor: pointer;
}

.vista-consulta-body {
  margin-top: 10px;
  padding: 10px;
   /* box-shadow: rgb(191, 191, 191) -1px 2px 5px; */
}

.filtros-consulta {
  display: flex;
  flex-wrap: wrap;
  gap: 1rem;
  justify-content: space-between;
  background: #fff;
  padding: 1rem;
  border-radius: 10px;
  box-shadow: rgb(191, 191, 191) -1px 2px 5px;
}

.filtro {
  flex: 1 1 70px;
  display: flex;
  flex-direction: column;
}

.filtro label {
  font-weight: bold;
  margin-bottom: 0.3rem;
}

.filtro .input {
  padding: 0.5rem;
  border: 1px solid #ccc;
  border-radius: 8px;
}

.filtro-grande {
  flex: 2 1 300px;
}

.filtro-consulta-linea {
  display: flex;
  flex-direction: row;
  align-items: flex-end;
  gap: 0.75rem;
  width: 100%;
}

.filtro-nro-venta {
  flex: 0 0 100px;
  width: 100px;
}

.filtro-nro-venta .input {
  box-sizing: border-box;
  width: 100%;
}

.filtro-paciente-consulta {
  flex: 1 1 auto;
  min-width: 0;
}

.busqueda-paciente {
  display: flex;
  gap: 0.5rem;
}

.busqueda-paciente input {
  flex: 1 1 auto;
  min-width: 0;
  width: 100%;
}

.busqueda-paciente .btn {
  flex: 0 0 auto;
}

.btn {
  background-color: #007bff;
  border: none;
  color: white;
  padding: 0.6rem 1rem;
  border-radius: 8px;
  cursor: pointer;
  transition: background-color 0.3s;
}

.btn:hover {
  background-color: #0056b3;
}




@media (max-width: 600px) {
  .vista-consulta-header {
    flex-direction: column;
    align-items: flex-start;
  }

  .filtros-consulta {
    flex-direction: column;
  }

  .busqueda-paciente {
    flex-direction: column;
  }

  .filtro-consulta-linea {
    flex-direction: column;
    align-items: stretch;
  }

  .filtro-nro-venta,
  .filtro-paciente-consulta {
    flex: 1 1 auto;
    width: 100%;
  }
}

.vista-consulta {
  opacity: 1;
  visibility: visible;
  transition: opacity 0.3s ease, visibility 0.3s ease;
}

.vista-consulta.hidden {
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
}

 
.campo-form {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
}

.campos-dobles {
  display: flex;
  gap: 1rem;
}

.campo-con-botones {
  display: flex;
  gap: 0.5rem;
}

.icon-btn {
  background: none;
  border: none;
  cursor: pointer;
}

.form-acciones {
  text-align: center;
}

 /* Contenedor principal en modo escritorio: horizontal */
.vista-consulta-body.contenedorflex {
  display: flex;
  flex-direction: row;
  gap: 1.5rem;
  flex-wrap: wrap;
  align-items: flex-start;
}

/* Formulario (izquierda) */
.formulario-agendamiento {
  flex: 1 1 30%;
  display: flex;
  flex-direction: column;
  gap: 1rem;
  padding: 1rem;
  border-radius: 10px;
  box-shadow: rgb(191, 191, 191) -1px 2px 5px;
  background-color: #fff;
  min-width: 300px;
}

