.magnifier-container {
  position: relative;
  cursor: crosshair;
  overflow: hidden;
}

.magnifier-glass {
  position: absolute;
  border: 3px solid #000;
  border-radius: 50%;
  cursor: none;
  width: 220px;
  height: 220px;
  opacity: 0;
  pointer-events: none;
  background-repeat: no-repeat;
  background-size: cover;
  z-index: 10;
  transition: opacity 0.2s ease-in-out;
 
}
 
  
