    :root{
      --bg: #f3f6fb;
      --panel: #ffffff;
      --text: #1f2937;
      --muted: #6b7280;

      --line: rgba(15, 23, 42, .10);
      --shadow: 0 10px 28px rgba(2, 6, 23, .10);

      --past: #f6d6d9;
      --today: #d9f1df;
      --next: #d8e9f9;

      --danger: #c0392b;
      --danger-bg: rgba(192,57,43,.12);

      --btn: rgba(15,23,42,.06);
      --btn-hover: rgba(15,23,42,.10);
    }

    *{ box-sizing:border-box; }
    body{
      margin:0;
      font-family: system-ui, -apple-system, Segoe UI, Roboto, Arial, sans-serif;
      background: var(--bg);
      color: var(--text);
    }

    .app{ 
      padding: 0 12px 18px;
    }

    /* Ventana */
    .window{
      background: var(--panel);
      border: 1px solid var(--line);
      border-radius: 14px;
      box-shadow: var(--shadow);
      overflow: hidden;
    }

    .titlebar{
      display:flex;
      align-items:center;
      justify-content:space-between;
      padding: 10px 14px;
      border-bottom: 1px solid var(--line);
      background: linear-gradient(to bottom, rgba(255,255,255,.95), rgba(255,255,255,.80));
    }

    .title-left{
      display:flex;
      align-items:center;
      gap:10px;
      min-width: 0;
    }

    .traffic{
      display:flex; gap:6px;
    }
    .dot{ width:10px; height:10px; border-radius:50%; }
    .dot.red{ background:#ff5f56; }
    .dot.yellow{ background:#ffbd2e; }
    .dot.green{ background:#27c93f; }

    .title{
      font-weight: 800;
      letter-spacing: .2px;
      white-space: nowrap;
      overflow: hidden;
      text-overflow: ellipsis;
    }

    .top-actions{
      display:flex;
      align-items:center;
      gap:10px;
      flex-wrap: wrap;
    }

    .chip{
      font-size: 12px;
      padding: 6px 10px;
      border-radius: 999px;
      background: rgba(15,23,42,.06);
      border: 1px solid var(--line);
      color: var(--text);
      font-weight: 700;
    }

    .btn{
      font-size: 12px;
      font-weight: 800;
      padding: 7px 10px;
      border-radius: 10px;
      border: 1px solid var(--line);
      background: var(--btn);
      color: var(--text);
      cursor: pointer;
      display:inline-flex;
      align-items:center;
      gap:8px;
      user-select:none;
    }
    .btn:hover{ background: var(--btn-hover); }
    .btn .plus{
      width:18px; height:18px; border-radius: 8px;
      display:grid; place-items:center;
      background: rgba(15,23,42,.10);
      font-weight: 900;
      line-height: 1;
    }

    /* Secciones */
    .content{ padding: 10px 12px 14px; }

    .section{
      border-radius: 14px;
      border: 1px solid var(--line);
      overflow: hidden;
      margin-top: 12px;
    }
    .section.past{ background: linear-gradient(to bottom, rgba(246,214,217,.95), rgba(246,214,217,.55)); }
    .section.today{ background: linear-gradient(to bottom, rgba(217,241,223,.95), rgba(217,241,223,.55)); }
    .section.next{ background: linear-gradient(to bottom, rgba(216,233,249,.95), rgba(216,233,249,.55)); }

    .section-head{
      padding: 10px 12px;
      display:flex;
      align-items:flex-end;
      justify-content: space-between;
      gap: 12px;
    }
    .section-title{
      font-weight: 900;
      font-size: 15px;
      margin:0;
    }
    .section-sub{
      margin: 2px 0 0;
      font-size: 12px;
      color: var(--muted);
      font-weight: 700;
    }

    .section-meta{
      text-align:right;
      font-size: 12px;
      color: var(--muted);
      font-weight: 800;
      white-space: nowrap;
    }

    .grid{
      padding: 10px 12px 12px;

    }

    @media (max-width: 820px){
      .grid{ grid-template-columns: 1fr; }
      .section-meta{ text-align:left; }
    }

    /* Tarjeta */
    .card{
      background: rgba(255,255,255,.70);
      border: 1px solid rgba(15,23,42,.10);
      border-radius: 14px;
      box-shadow: 0 10px 22px rgba(2, 6, 23, .06);
      padding: 10px;
      display:flex;
      gap: 10px;
      position: relative;
      min-height: 98px;
    }

    .iconbox{
      width: 58px;
      min-width: 58px;
      height: 58px;
      border-radius: 14px;
      background: rgba(15,23,42,.06);
      border: 1px solid rgba(15,23,42,.10);
      display:grid;
      place-items:center;
    }
    /* Icono simple tipo “carpeta/caja” */
    .ic{
      width: 34px; height: 34px;
      position: relative;
    }
    .ic::before, .ic::after{
      content:"";
      position:absolute;
      border: 2px solid rgba(15,23,42,.55);
      border-radius: 8px;
      width: 30px; height: 18px;
      left: 2px; top: 10px;
      background: rgba(255,255,255,.35);
    }
    .ic::after{
      width: 22px; height: 10px;
      top: 4px; left: 2px;
      border-bottom: 0;
      border-bottom-left-radius: 0;
      border-bottom-right-radius: 0;
    }

    .card-body{
      flex:1;
      min-width:0;
    }

    .card-top{
      display:flex;
      align-items:flex-start;
      justify-content:space-between;
      gap: 10px;
    }

    .card-title{
      font-weight: 900;
      font-size: 12px;
      letter-spacing: .2px;
      margin: 0 0 4px;
      text-transform: uppercase;
    }
    .card-title span{
      font-weight: 800;
      text-transform:none;
      letter-spacing:0;
    }

    .lines{
      display:grid;
      grid-template-columns: 3fr 1fr;
      gap: 2px 10px;
      margin-top: 4px;
      font-size: 12px;
      color: rgba(31,41,55,.92);
    }

    @media (max-width: 520px){
      .lines{ grid-template-columns: 1fr; }
    }

    .line b{
      font-weight: 900;
      color: rgba(31,41,55,.92);
    }
    .line{
      white-space: nowrap;
      overflow: hidden;
      text-overflow: ellipsis;
    }

    .actions{
      display:flex;
      gap: 6px;
      align-items:center;
    }

    .iconbtn{
      width: 28px; height: 28px;
      border-radius: 10px;
      border: 1px solid rgba(15,23,42,.12);
      background: rgba(15,23,42,.06);
      display:grid;
      place-items:center;
      cursor:pointer;
      user-select:none;
      font-weight: 900;
      color: rgba(15,23,42,.70);
    }
    .iconbtn:hover{ background: rgba(15,23,42,.10); }

