    /* Subtítulos dentro de "Próximos" */
    .subgroup{
      padding: 0 12px 10px;
    }
    .subgroup-title{
      margin: 0;
      font-size: 12px;
      font-weight: 900;
      color: rgba(15,23,42,.70);
      padding-top: 8px;
    }

    .footer-cta{
      display:flex;
      justify-content:center;
