    background: #ffffff;
    border: 1px solid #e2e8f0;
    border-radius: 20px;
    padding: 14px;
    cursor: pointer;
    transition: 0.2s ease;
    box-shadow: 0 10px 24px rgba(15, 23, 42, 0.06);
    overflow: hidden;
}

.asignar-tarea__card:hover {
    transform: translateY(-4px);
    border-color: #2563eb;
    box-shadow: 0 18px 34px rgba(15, 23, 42, 0.12);
}

.asignar-tarea__card--activo {
    border-color: #16a34a;
    background: linear-gradient(180deg, #ffffff, #f0fdf4);
}

.asignar-tarea__foto {
    width: 112px;
    height: 112px;
    border-radius: 32px;
    object-fit: cover;
    object-position: center;
    display: block;
    margin: 0 auto 14px;
    background: #e2e8f0;
    border: 4px solid #f8fafc;
}

.asignar-tarea__nombre {
    margin: 0;
    text-align: center;
    font-size: 15px;
    color: #0f172a;
    font-weight: 800;
}

.asignar-tarea__login {
    margin: 4px 0 0;
    text-align: center;
    color: #64748b;
    font-size: 13px;
}

.asignar-tarea__tipo {
    display: inline-flex;
    justify-content: center;
    width: 100%;
    margin-top: 10px;
}

.asignar-tarea__badge {
    padding: 5px 10px;
    border-radius: 999px;
    background: #eff6ff;
    color: #1d4ed8;
    font-size: 11px;
    font-weight: 800;
    text-transform: uppercase;
}

.asignar-tarea__vacio {
    min-height: 300px;
    display: grid;
    place-items: center;
    color: #64748b;
    text-align: center;
    font-weight: 600;
}

@media (max-width: 850px) {
    .asignar-tarea {
        padding: 12px;
    }

    .asignar-tarea__header {
        align-items: flex-start;
    }

    .asignar-tarea__filtros {
        grid-template-columns: 1fr;
    }

    .asignar-tarea__seleccion {
        align-items: flex-start;
        flex-direction: column;
    }

    .asignar-tarea__btn-confirmar {
        width: 100%;
    }
}



