.perfil-tareas {
    background: #ffffff;
    border: 1px solid #e2e8f0;
    border-radius: 10px;
    padding: 5px;
    box-shadow: 0 14px 35px rgba(15, 23, 42, 0.08);
}

.perfil-tareas__cabecera {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
    margin-bottom: 5px;
}

.perfil-tareas__titulo {
    margin: 0;
    color: #0f172a;
    font-size: 17px;
    font-weight: 900;
}

.perfil-tareas__subtitulo {
    margin: 3px 0 0;
    color: #64748b;
