}

.perfil-tareas__contador {
    padding: 8px 12px;
    border-radius: 999px;
    background: #eff6ff;
    color: #1d4ed8;
    font-size: 13px;
    font-weight: 900;
}

.perfil-tareas__lista {
    display: grid;
    gap: 2px;
}

.perfil-tareas__item {
    display: grid;
    grid-template-columns: auto 1fr auto;
    align-items: flex-start;
    gap: 5px;
    padding: 5px;
    border: 1px solid #e2e8f0;
