}

.perfil-tareas__check {
    width: 18px;
    height: 18px;
    margin-top: 4px;
}

.perfil-tareas__descripcion {
    margin: 0;
    color: #0f172a;
    font-size: 14px;
    font-weight: 900;
}

.perfil-tareas__meta {
    margin: 4px 0 0;
    color: #64748b;
    font-size: 12px;
    font-weight: 600;
}

.perfil-tareas__observacion {
    margin: 8px 0 0;
    padding: 8px 10px;
    border-radius: 12px;
    background: #ffffff;
    color: #475569;
    font-size: 12px;
    border: 1px dashed #cbd5e1;
}

.perfil-tareas__estado {
    padding: 6px 9px;
    border-radius: 999px;
    font-size: 11px;
    font-weight: 900;
    text-transform: uppercase;
    white-space: nowrap;
}

.perfil-tareas__estado--pendiente {
    background: #fef3c7;
    color: #92400e;
}

.perfil-tareas__estado--proceso {
    background: #dbeafe;
    color: #1d4ed8;
}

.perfil-tareas__vacio {
    margin-top: 12px;
    padding: 20px;
    text-align: center;
    color: #64748b;
    background: #f8fafc;
    border: 1px dashed #cbd5e1;
    border-radius: 18px;
    font-weight: 700;
}

.perfil-tareas__item--completada {
    opacity: 0.65;
    background: #f1f5f9;
}

.perfil-tareas__item--completada .perfil-tareas__descripcion,
.perfil-tareas__item--completada .perfil-tareas__meta {
    text-decoration: line-through;
}

.perfil-tareas__item--cancelada {
    opacity: 0.55;
    background: #fef2f2;
}

.perfil-tareas__item--cancelada .perfil-tareas__descripcion,
.perfil-tareas__item--cancelada .perfil-tareas__meta {
    text-decoration: line-through;
}

.perfil-tareas__estado--completada {
    background: #dcfce7;
    color: #166534;
}

.perfil-tareas__estado--cancelada {
    background: #fee2e2;
    color: #991b1b;
}

.perfil-tareas__check:disabled {
    cursor: not-allowed;
    opacity: 0.6;
}


.perfil-tareas__contador {
    position: relative;
    display: inline-flex;
    align-items: center;
    gap: 6px;
    padding: 9px 14px;
    border-radius: 999px;
    background: #f1f5f9;
    color: #64748b;
    font-size: 13px;
    font-weight: 800;
    box-shadow: inset 0 0 0 1px #e2e8f0;
    transition: all 0.25s ease;
}

.perfil-tareas__contador span {
    min-width: 24px;
    height: 24px;
    padding: 0 7px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    border-radius: 999px;
    background: #cbd5e1;
    color: #ffffff;
    font-size: 13px;
    font-weight: 900;
}

/* Cuando tiene tareas pendientes */
.perfil-tareas__contador--alerta {
    background: linear-gradient(135deg, #fff7ed, #fee2e2);
    color: #991b1b;
    box-shadow: 
        0 0 0 1px rgba(239, 68, 68, 0.25),
        0 10px 22px rgba(239, 68, 68, 0.22);
    animation: perfilTareasPulso 1.4s ease-in-out infinite;
}

.perfil-tareas__contador--alerta span {
    background: linear-gradient(135deg, #ef4444, #f97316);
    color: #ffffff;
    box-shadow: 0 6px 14px rgba(239, 68, 68, 0.35);
}

.perfil-tareas__contador--alerta::after {
    content: "";
    position: absolute;
    top: -3px;
    right: -3px;
    width: 11px;
    height: 11px;
    border-radius: 50%;
    background: #ef4444;
    border: 2px solid #ffffff;
    box-shadow: 0 0 0 4px rgba(239, 68, 68, 0.18);
}

@keyframes perfilTareasPulso {
    0% {
        transform: scale(1);
        box-shadow: 
            0 0 0 1px rgba(239, 68, 68, 0.25),
            0 10px 22px rgba(239, 68, 68, 0.22);
    }

    50% {
        transform: scale(1.04);
        box-shadow: 
            0 0 0 1px rgba(239, 68, 68, 0.35),
            0 14px 28px rgba(239, 68, 68, 0.32);
    }

    100% {
        transform: scale(1);
        box-shadow: 
            0 0 0 1px rgba(239, 68, 68, 0.25),
            0 10px 22px rgba(239, 68, 68, 0.22);
    }
}

