    gap: 6px;
}

.asignar-tarea__role-detail-grid span {
    display: inline-flex;
    align-items: center;
    max-width: 100%;
    min-height: 24px;
    padding: 4px 8px;
    border-radius: 999px;
    background: #f8fafc;
    color: #475569;
    font-size: 11px;
    font-weight: 800;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.asignar-tarea__funcionario-card.asignar-tarea__user-row {
    display: block;
