}

.asignar-tarea__funcionario-summary {
    display: grid;
    grid-template-columns: minmax(220px, 1.15fr) minmax(210px, .95fr) minmax(220px, 1.05fr) minmax(100px, .45fr) 22px;
    gap: 10px;
    align-items: center;
    min-height: 64px;
    padding: 9px 12px;
    cursor: pointer;
