}

.asignar-tarea__funcionario-card--abierto .asignar-tarea__funcionario-summary {
    background: #f8fafc;
    border-bottom: 1px solid #e2e8f0;
}

.asignar-tarea__jornada-badge {
    display: inline-flex;
    align-items: center;
    min-height: 24px;
    padding: 4px 8px;
    border-radius: 999px;
    background: #f1f5f9;
    color: #475569;
    font-size: 11px;
    font-weight: 900;
}

.asignar-tarea__jornada-badge--completa {
    background: #dcfce7;
    color: #166534;
}

.asignar-tarea__jornada-badge--atrasada {
    background: #fee2e2;
    color: #b42318;
}

.asignar-tarea__jornada-badge--en-curso {
    background: #eff6ff;
    color: #1d4ed8;
}

.asignar-tarea__user-stats--compact {
