    grid-template-columns: minmax(0, 1fr) auto;
    gap: 7px;
    align-items: center;
}

.asignar-tarea__progress div {
    height: 7px;
    overflow: hidden;
    border-radius: 99px;
    background: #e2e8f0;
}

.asignar-tarea__progress i {
    display: block;
    height: 100%;
    border-radius: inherit;
    background: #16a34a;
}

.asignar-tarea__progress strong {
    color: #0f172a;
    font-size: 12px;
    font-weight: 900;
}

.asignar-tarea__progress--empty {
    display: block;
}

.asignar-tarea__chevron {
    width: 20px;
    height: 20px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    color: #64748b;
}

.asignar-tarea__chevron::before {
    content: "\203A";
    display: block;
    font-size: 22px;
    font-weight: 900;
    line-height: 1;
    transform: rotate(90deg);
    transition: transform .16s ease;
}

.asignar-tarea__funcionario-card--abierto .asignar-tarea__chevron::before {
    transform: rotate(-90deg);
    color: #1d4ed8;
}

.asignar-tarea__funcionario-detail {
    padding: 10px 12px 12px;
    background: #ffffff;
}

.asignar-tarea__task-panel {
    display: grid;
    gap: 10px;
    padding: 2px;
}

.asignar-tarea__task-panel-head {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 10px;
    padding: 10px;
    border: 1px solid #e2e8f0;
    border-radius: 8px;
    background: #f8fafc;
}

.asignar-tarea__task-panel-head h3,
.asignar-tarea__task-panel-head span {
    margin: 0;
}

.asignar-tarea__task-panel-head h3 {
    color: #0f172a;
    font-size: 14px;
    font-weight: 900;
}

.asignar-tarea__task-panel-head span {
    display: block;
    margin-top: 2px;
    color: #64748b;
    font-size: 11px;
    font-weight: 800;
}

.asignar-tarea__task-sections {
    display: grid;
    gap: 10px;
}

.asignar-tarea__task-section {
    border: 1px solid #e2e8f0;
    border-radius: 8px;
    background: #ffffff;
}

.asignar-tarea__task-section-head {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 10px;
    padding: 9px 10px;
    border-bottom: 1px solid #edf2f7;
    background: #f8fafc;
}

.asignar-tarea__task-section-head h4 {
    margin: 0;
    color: #0f172a;
    font-size: 12px;
    font-weight: 900;
}

.asignar-tarea__task-section-head span {
    min-width: 24px;
    min-height: 22px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    border-radius: 999px;
    background: #e2e8f0;
    color: #334155;
    font-size: 11px;
    font-weight: 900;
}

.asignar-tarea__task-list {
    display: grid;
    gap: 6px;
    padding: 8px;
}

.asignar-tarea__task-row {
    display: grid;
    grid-template-columns: 56px minmax(0, 1fr) minmax(104px, 132px) 28px;
    gap: 8px;
    align-items: center;
    min-height: 48px;
    padding: 7px 8px;
    border: 1px solid #edf2f7;
    border-radius: 8px;
    background: #ffffff;
}

.asignar-tarea__task-row--atrasada {
    border-color: #fecaca;
    background: #fff7f7;
}

.asignar-tarea__task-row--completada {
    background: #f8fafc;
    opacity: .76;
}

.asignar-tarea__task-row--completada-tarde {
    border-color: #fed7aa;
    background: #fffaf5;
}

.asignar-tarea__task-time {
    color: #0f172a;
    font-size: 12px;
    font-weight: 900;
}

.asignar-tarea__task-copy {
    min-width: 0;
    display: grid;
    gap: 3px;
}

.asignar-tarea__task-copy strong {
    color: #0f172a;
    font-size: 12px;
    font-weight: 900;
    line-height: 1.25;
}

.asignar-tarea__task-row--completada .asignar-tarea__task-copy strong {
    text-decoration: line-through;
}

.asignar-tarea__task-copy small {
    display: flex;
    flex-wrap: wrap;
    gap: 4px 8px;
    color: #64748b;
    font-size: 10px;
    font-weight: 800;
    line-height: 1.2;
}

.asignar-tarea__task-note {
    color: #475569 !important;
}

.asignar-tarea__task-status {
    justify-self: start;
    max-width: 132px;
    padding: 4px 7px;
    border-radius: 999px;
    font-size: 10px;
    font-weight: 900;
    line-height: 1.1;
}

.asignar-tarea__task-status--pendiente {
    background: #f1f5f9;
    color: #475569;
}

.asignar-tarea__task-status--proceso {
    background: #eff6ff;
    color: #1d4ed8;
}

.asignar-tarea__task-status--atrasada {
    background: #fee2e2;
    color: #b42318;
}

.asignar-tarea__task-status--completada {
    background: #dcfce7;
    color: #166534;
}

.asignar-tarea__task-status--completada-tarde {
    background: #ffedd5;
    color: #9a3412;
}

.asignar-tarea__task-status--cancelada {
    background: #f1f5f9;
    color: #667085;
}

.asignar-tarea__task-check {
    width: 20px;
    height: 20px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
}

.asignar-tarea__task-check input {
    width: 18px;
    height: 18px;
    margin: 0;
    accent-color: #16a34a;
}

.asignar-tarea__task-action--done {
    width: 20px;
    height: 20px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    border-radius: 50%;
    background: #dcfce7;
    color: #166534;
    font-size: 12px;
    font-weight: 900;
}

.asignar-tarea__task-empty {
    padding: 10px;
    border: 1px dashed #cbd5e1;
    border-radius: 8px;
    color: #64748b;
    font-size: 11px;
    font-weight: 800;
    background: #f8fafc;
}

.asignar-tarea__inline-add {
    display: grid;
    gap: 8px;
}

.asignar-tarea__inline-add-btn,
.asignar-tarea__inline-actions button {
    width: fit-content;
    min-height: 30px;
    padding: 0 10px;
    border: 1px solid #bfdbfe;
    border-radius: 8px;
    background: #2563eb;
    color: #ffffff;
    font-size: 11px;
    font-weight: 900;
    cursor: pointer;
}

.asignar-tarea__inline-form {
    display: grid;
    gap: 8px;
    padding: 10px;
    border: 1px solid #dbeafe;
    border-radius: 8px;
    background: #f8fbff;
}

.asignar-tarea__inline-grid {
    display: grid;
    grid-template-columns: minmax(0, 1fr) 120px 150px 140px;
    gap: 8px;
}

.asignar-tarea__inline-grid .inputText,
.asignar-tarea__inline-textarea {
    width: 100% !important;
    min-width: 0;
    box-sizing: border-box;
}

.asignar-tarea__inline-textarea {
    min-height: 54px;
    resize: vertical;
}

.asignar-tarea__inline-actions {
    display: flex;
    gap: 8px;
    justify-content: flex-end;
}

.asignar-tarea__inline-actions button:last-child {
    background: #ffffff;
    color: #334155;
    border-color: #cbd5e1;
}

.asignar-tarea__inline-form small {
    color: #64748b;
    font-size: 10.5px;
    font-weight: 800;
}

@media (max-width: 1050px) {
    .asignar-tarea__funcionario-summary,
    .asignar-tarea__role-summary {
        grid-template-columns: 1fr;
        align-items: start;
    }

    .asignar-tarea__progress {
        max-width: 260px;
    }

    .asignar-tarea__inline-grid,
    .asignar-tarea__task-row {
        grid-template-columns: 1fr;
    }

    .asignar-tarea__task-status {
        max-width: 100%;
    }
}

/* Panel lateral de usuario compacto */
.perfil-app {
    width: 35%;
    min-width: 320px;
    vertical-align: top;
    padding: 8px 10px !important;
    border-left: 1px solid #dbe3ea !important;
    background: #f8fafc !important;
    box-sizing: border-box;
}

.perfil-widget {
    width: 100%;
    max-width: 430px;
    margin: 0 auto;
    display: grid;
    gap: 8px;
    color: #172033;
}

.perfil-widget__usuario,
.perfil-widget__jornada,
.perfil-tareas {
    background: #ffffff !important;
    border: 1px solid #e4e7ec !important;
    border-radius: 10px !important;
    box-shadow: 0 8px 22px rgba(15, 23, 42, 0.08) !important;
}

.perfil-widget__usuario {
    display: grid;
    grid-template-columns: 64px minmax(0, 1fr);
    align-items: center;
    gap: 10px;
    padding: 10px;
    box-sizing: border-box;
}

.perfil-widget__avatar-wrap {
    position: relative;
    width: 64px;
    height: 64px;
}

.perfil-app__foto {
    width: 64px !important;
    height: 64px !important;
    aspect-ratio: 1 / 1;
    object-fit: cover;
    object-position: center;
    display: block;
    border-radius: 50% !important;
    border: 2px solid #e4e7ec !important;
    background-color: #f8fafc !important;
}

.perfil-app__editar {
    position: absolute;
    right: -4px !important;
    bottom: -4px !important;
    width: 24px !important;
    height: 24px !important;
    padding: 4px !important;
    border-radius: 8px !important;
    border: 1px solid #ffffff;
    background: #eef2f7 !important;
    box-shadow: 0 5px 12px rgba(15, 23, 42, 0.18);
    cursor: pointer;
    box-sizing: border-box;
}

.perfil-widget__info {
    min-width: 0;
}

.perfil-widget__nombre {
    margin: 0;
    color: #172033;
    font-size: 14px;
    font-weight: 800;
    line-height: 1.2;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.perfil-widget__rol {
    margin: 2px 0 0;
    color: #667085;
    font-size: 11px;
    font-weight: 700;
}

.perfil-widget__chips {
