/* Configuracion de accesos rapidos por usuario */
.dashboard-shortcut-modal {
    position: fixed;
    inset: 0;
    z-index: 100000;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 18px;
    box-sizing: border-box;
    font-family: "Merriweather Sans", Arial;
}

.dashboard-shortcut-modal__backdrop {
    position: absolute;
    inset: 0;
    background: rgba(15, 23, 42, 0.48);
}

.dashboard-shortcut-modal__panel {
    position: relative;
    z-index: 1;
    width: min(980px, 96vw);
    max-height: 88vh;
    display: flex;
    flex-direction: column;
    overflow: hidden;
    border-radius: 8px;
    border: 1px solid #d9e1ea;
    background: #ffffff;
    box-shadow: 0 24px 60px rgba(15, 23, 42, 0.22);
}

.dashboard-shortcut-modal__header {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 14px;
    padding: 14px 16px 12px;
    border-bottom: 1px solid #edf1f5;
}

.dashboard-shortcut-modal__eyebrow {
    margin: 0 0 3px;
    color: #667085;
    font-size: 10px;
    font-weight: 900;
    line-height: 1.1;
    text-transform: uppercase;
}

.dashboard-shortcut-modal__header h3 {
    margin: 0;
    color: #172033;
    font-size: 17px;
    font-weight: 900;
    line-height: 1.2;
}

.dashboard-shortcut-modal__close {
    width: 30px;
    height: 30px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    border: 1px solid #e4e7ec;
    border-radius: 999px;
    background: #f8fafc;
    color: #172033;
    cursor: pointer;
    font-size: 14px;
    font-weight: 900;
    line-height: 1;
}

.dashboard-shortcut-modal__toolbar {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 10px;
    padding: 12px 16px;
    border-bottom: 1px solid #edf1f5;
}

.dashboard-shortcut-modal__search {
    width: min(360px, 100%);
    height: 34px;
    padding: 7px 10px;
    box-sizing: border-box;
    border: 1px solid #d9e1ea;
    border-radius: 8px;
    background: #ffffff;
    color: #172033;
    font-family: "Merriweather Sans", Arial;
    font-size: 12px;
    font-weight: 700;
    outline: none;
}

.dashboard-shortcut-modal__search:focus {
    border-color: #93c5fd;
    box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.12);
}

.dashboard-shortcut-modal__limit {
    padding: 6px 10px;
    border-radius: 999px;
    background: #f8fafc;
    border: 1px solid #e4e7ec;
    color: #475467;
    font-size: 11px;
    font-weight: 900;
    white-space: nowrap;
}

.dashboard-shortcut-modal__body {
    display: grid;
    grid-template-columns: minmax(0, 1fr) 310px;
    gap: 14px;
    min-height: 0;
    padding: 14px 16px;
    background: #f8fafc;
    overflow: auto;
}

.dashboard-shortcut-modal__catalog {
    min-width: 0;
    display: grid;
    gap: 12px;
}

.dashboard-shortcut-group {
    padding: 10px;
    border: 1px solid #e4e7ec;
    border-radius: 8px;
    background: #ffffff;
}

.dashboard-shortcut-group h4 {
    margin: 0 0 9px;
    color: #172033;
    font-size: 13px;
    font-weight: 900;
    line-height: 1.2;
}

.dashboard-shortcut-options {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(150px, 1fr));
    gap: 8px;
}

.dashboard-shortcut-option {
    min-height: 42px;
    display: grid;
    grid-template-columns: 18px 24px minmax(0, 1fr);
    align-items: center;
    gap: 7px;
    padding: 7px;
    box-sizing: border-box;
    border: 1px solid #edf1f5;
    border-radius: 8px;
    background: #ffffff;
    color: #172033;
    cursor: pointer;
    font-size: 11px;
    font-weight: 800;
    line-height: 1.2;
}

.dashboard-shortcut-option:hover {
    border-color: #cbd5e1;
    background: #f8fafc;
}

.dashboard-shortcut-option input {
    width: 14px;
    height: 14px;
    margin: 0;
}

.dashboard-shortcut-option img {
    width: 22px;
    height: 22px;
    object-fit: contain;
}

.dashboard-shortcut-option span {
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: normal;
    display: -webkit-box;
    -webkit-line-clamp: 2;
    -webkit-box-orient: vertical;
}

.dashboard-shortcut-modal__preview {
    min-width: 0;
    align-self: start;
    position: sticky;
    top: 0;
    padding: 10px;
    border: 1px solid #e4e7ec;
    border-radius: 8px;
    background: #ffffff;
}

.dashboard-shortcut-modal__preview-header {
    display: grid;
    gap: 2px;
    margin-bottom: 9px;
}

.dashboard-shortcut-modal__preview-header strong {
    color: #172033;
    font-size: 13px;
    font-weight: 900;
}

.dashboard-shortcut-modal__preview-header small {
    color: #667085;
    font-size: 10px;
    font-weight: 700;
}

#dashboardShortcutPreview {
    display: grid;
    gap: 7px;
    min-height: 54px;
    max-height: 430px;
    overflow: auto;
}

.dashboard-shortcut-preview-item {
    min-height: 42px;
    display: grid;
    grid-template-columns: 26px 22px 24px minmax(0, 1fr) 26px 26px 26px;
    align-items: center;
    gap: 6px;
    padding: 6px;
    border: 1px solid #edf1f5;
    border-radius: 8px;
    background: #f8fafc;
}

.dashboard-shortcut-modal--dragging #dashboardShortcutPreview {
    border-radius: 8px;
    outline: 2px dashed #93c5fd;
    outline-offset: 3px;
}

.dashboard-shortcut-preview-item[draggable="true"],
.dashboard-shortcut-option[draggable="true"] {
    cursor: grab;
}

.dashboard-shortcut-preview-item[draggable="true"]:active,
.dashboard-shortcut-option[draggable="true"]:active {
    cursor: grabbing;
}

.dashboard-shortcut-drag-handle {
    width: 26px;
    height: 26px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    border: 1px solid #d9e1ea;
    border-radius: 8px;
    background: #ffffff;
    color: #64748b;
    cursor: grab;
    font-size: 12px;
    font-weight: 950;
    line-height: 1;
    touch-action: none;
}

.dashboard-shortcut-drag-handle:active {
    cursor: grabbing;
}

.dashboard-shortcut-preview-item__order {
    width: 22px;
    height: 22px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    border-radius: 999px;
    background: #ffffff;
    border: 1px solid #e4e7ec;
    color: #475467;
    font-size: 10px;
    font-weight: 900;
}

.dashboard-shortcut-preview-item img {
    width: 22px;
    height: 22px;
    object-fit: contain;
}

.dashboard-shortcut-preview-item__label {
    min-width: 0;
    color: #172033;
    font-size: 11px;
    font-weight: 800;
    line-height: 1.15;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.dashboard-shortcut-preview-item button {
    width: 26px;
    height: 26px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    border: 1px solid #e4e7ec;
    border-radius: 8px;
    background: #ffffff;
    color: #172033;
    cursor: pointer;
    font-size: 11px;
    font-weight: 900;
}

.dashboard-shortcut-preview-item button:hover {
    border-color: #cbd5e1;
    background: #ffffff;
}

.dashboard-shortcut-preview-item .dashboard-shortcut-drag-handle {
    color: #64748b;
    cursor: grab;
    font-size: 12px;
    touch-action: none;
}

.dashboard-shortcut-preview-item .dashboard-shortcut-drag-handle:active {
    cursor: grabbing;
}

.dashboard-shortcut-empty {
    padding: 12px;
    border: 1px dashed #cbd5e1;
    border-radius: 8px;
    background: #ffffff;
    color: #667085;
    font-size: 12px;
    font-weight: 800;
    text-align: center;
}

.dashboard-shortcut-modal__footer {
    display: flex;
    flex-wrap: wrap;
    justify-content: flex-end;
    gap: 8px;
    padding: 12px 16px;
    border-top: 1px solid #edf1f5;
    background: #ffffff;
}

.dashboard-shortcut-modal__btn {
    min-height: 34px;
    padding: 8px 13px;
    border-radius: 999px;
    cursor: pointer;
    font-family: "Merriweather Sans", Arial;
    font-size: 12px;
    font-weight: 900;
}

.dashboard-shortcut-modal__btn--secondary {
    border: 1px solid #d9e1ea;
    background: #ffffff;
    color: #172033;
}

.dashboard-shortcut-modal__btn--primary {
    border: 1px solid #2563eb;
    background: #2563eb;
    color: #ffffff;
}

@media (max-width: 820px) {
    .dashboard-shortcut-modal__body {
        grid-template-columns: 1fr;
    }

    .dashboard-shortcut-modal__preview {
        position: static;
    }
}

@media (max-width: 620px) {
    .dashboard-shortcut-modal {
        padding: 10px;
    }

    .dashboard-shortcut-modal__panel {
        width: 100%;
        max-height: 92vh;
    }

    .dashboard-shortcut-modal__header,
    .dashboard-shortcut-modal__toolbar,
    .dashboard-shortcut-modal__body,
    .dashboard-shortcut-modal__footer {
        padding-left: 10px;
        padding-right: 10px;
    }

    .dashboard-shortcut-modal__toolbar {
        align-items: flex-start;
        flex-direction: column;
    }

    .dashboard-shortcut-modal__search {
        width: 100%;
    }

    .dashboard-shortcut-options {
        grid-template-columns: 1fr;
    }

    .dashboard-shortcut-preview-item {
        grid-template-columns: 22px 24px minmax(0, 1fr) 24px 24px 24px;
    }
}

